print("Illegal NS->S Jump Detection:  ", illegal_jump["action"])
print("TrustZone Invariant: Direct jumps from Non-Secure to Secure trigger immediate SecureFault.")

# TrustZone Dual Vector Tables & Secure Exception Priority Simulator
class TrustZoneInterruptController:
    def __init__(self):
        # Dual Vector Tables
        self.vector_tables = {
            "SECURE": {"Reset": 0x10000004, "SecureFault": 0x10000010, "Tamper_IRQ": 0x10000040},
            "NON_SECURE": {"Reset": 0x00022004, "HardFault": 0x00022010, "Timer_IRQ": 0x00022040}
        }
        # Interrupt Security Target: 0 = Secure, 1 = Non-Secure
        self.NVIC_ITNS = {"Tamper_IRQ": 0, "Timer_IRQ": 1}

    def dispatch_interrupt(self, irq_name: str, cpu_domain: str) -> dict:
        target = self.NVIC_ITNS.get(irq_name)
        if target is None:
            return {"status": "UNKNOWN_INTERRUPT"}

        # AIRCR.PRIS (Priority Inversion Shield): Secure interrupts always de-prioritize NS
        if target == 0:  # Secure interrupt
            return {
                "irq": irq_name,
                "handler_domain": "SECURE",
                "vector_address": hex(self.vector_tables["SECURE"][irq_name]),
                "preempts_non_secure": True
            }
        else:  # Non-Secure interrupt
            return {
                "irq": irq_name,
                "handler_domain": "NON_SECURE",
                "vector_address": hex(self.vector_tables["NON_SECURE"][irq_name]),
                "preempts_non_secure": (cpu_domain == "NON_SECURE")
            }

nvic = TrustZoneInterruptController()
tamper = nvic.dispatch_interrupt("Tamper_IRQ", cpu_domain="NON_SECURE")
timer = nvic.dispatch_interrupt("Timer_IRQ", cpu_domain="NON_SECURE")

print("=== TrustZone Dual Vector Table & Interrupt Dispatch ===")
print(f"Tamper Alarm (Physical Breach): Handler -> {tamper['handler_domain']} (Preempts NS: {tamper['preempts_non_secure']})")
print(f"Timer IRQ (Application Tick):   Handler -> {timer['handler_domain']} (Vector: {timer['vector_address']})")
print("NVIC Invariant: Secure interrupts cannot be masked or disabled by Non-Secure firmware.")

# ARMv8-M PMSAv8 MPU Region Configuration Simulator
class PMSAv8MPURegion:
    def __init__(self, rnr, base_addr, limit_addr, access_perm, is_executable=False):
        self.rnr = rnr
        self.base_addr = base_addr & ~0x1F   # 32-byte aligned base
        self.limit_addr = limit_addr | 0x1F  # 32-byte aligned limit
        self.access_perm = access_perm       # 'RO', 'RW', 'NO_ACCESS', 'PRIV_RW'
        self.is_executable = is_executable

    def check_access(self, addr: int, is_write: bool, is_fetch: bool, is_privileged: bool) -> bool:
        if not (self.base_addr <= addr <= self.limit_addr):
            return False
        if is_fetch and not self.is_executable:
            return False  # Execute-Never (XN) violation
        if is_write:
            if self.access_perm == 'NO_ACCESS':
                return False
            if self.access_perm == 'RO':
                return False
            if self.access_perm == 'PRIV_RW' and not is_privileged:
                return False
        return True

mpu_flash = PMSAv8MPURegion(rnr=0, base_addr=0x00022000, limit_addr=0x0007FFFF, access_perm='RO', is_executable=True)
mpu_sram  = PMSAv8MPURegion(rnr=1, base_addr=0x20000000, limit_addr=0x2001FFFF, access_perm='RW', is_executable=False)

print("=== ARMv8-M PMSAv8 MPU Region Audit ===")
print("Flash Executable Fetch (0x00025000):", mpu_flash.check_access(0x00025000, is_write=False, is_fetch=True, is_privileged=False))
print("Flash Write Attempt (0x00025000):   ", mpu_flash.check_access(0x00025000, is_write=True, is_fetch=False, is_privileged=False))
print("SRAM Code Execution (0x20004000):   ", mpu_sram.check_access(0x20004000, is_write=False, is_fetch=True, is_privileged=False))
print("MPU Invariant: PMSAv8 enforces 32-byte limit boundaries and Execute-Never (XN) on SRAM.")

# Privileged Handler Mode vs Unprivileged Thread Mode (CONTROL.nPRIV) Simulator
class CPUExecutionPrivilegeLevel:
    def __init__(self):
        self.mode = "THREAD"       # "THREAD" or "HANDLER"
        self.npriv = 0             # 0 = Privileged, 1 = Unprivileged
        self.privileged_peripherals = (0x40000000, 0x4000FFFF)

    def is_privileged(self) -> bool:
        # Handler mode (ISRs) is ALWAYS privileged regardless of nPRIV
        if self.mode == "HANDLER":
            return True
        return self.npriv == 0

    def access_system_control_block(self) -> dict:
        if not self.is_privileged():
            return {
                "access": "DENIED",
                "fault": "BUS_FAULT_UNPRIVILEGED_SCB_WRITE",
                "trap": "MemManage_Exception"
            }
        return {"access": "GRANTED", "fault": "NONE", "trap": "NONE"}

cpu = CPUExecutionPrivilegeLevel()
# Thread mode drops privileges to run unprivileged user task
cpu.npriv = 1
user_scb = cpu.access_system_control_block()

# Interrupt occurs, CPU enters Handler mode (automatically privileged)
cpu.mode = "HANDLER"
isr_scb = cpu.access_system_control_block()

print("=== CPU Privilege Level Enforcement ===")
print(f"User Thread SCB Access (nPRIV=1): {user_scb['access']} ({user_scb['trap']})")
print(f"Handler ISR SCB Access:           {isr_scb['access']} ({isr_scb['trap']})")
print("Privilege Invariant: Unprivileged user threads are blocked from reconfiguring system control blocks.")

# ARMv8-M Secure Gateway (SG) Veneer & NSC Entry Point Simulator
class SecureGatewayVeneerTable:
    def __init__(self):
        # NSC memory window: 0x00040000 - 0x00040FFF
        # Each veneer entry consists of:
        # [0x00] SG instruction (0xE97FE97F)
        # [0x04] B.W target_secure_function
        self.nsc_veneers = {
            0x00040000: {"symbol": "nsc_crypto_sign",    "target": 0x10002100, "has_sg": True},
            0x00040008: {"symbol": "nsc_read_device_id", "target": 0x10002240, "has_sg": True}
        }
        self.secure_private_functions = {
            0x10002100: "private_sign_internal_logic",
            0x10002150: "private_extract_raw_private_key"  # Mid-function or unexported secret
        }

    def branch_from_non_secure(self, destination_address: int) -> dict:
        # Check if destination address has the SG instruction in NSC region
        veneer = self.nsc_veneers.get(destination_address)
        if veneer and veneer["has_sg"]:
            return {
                "status": "GATEWAY_AUTHORIZED",
                "service": veneer["symbol"],
                "target_secure_address": hex(veneer["target"]),
                "cpu_state": "TRANSITION_TO_SECURE"
            }

        # Illegal attempt to jump directly to private Secure functions bypassing SG
        return {
            "status": "ILLEGAL_ENTRY_REJECTED",
            "fault": "SECUREFAULT_INVEP_INVALID_ENTRY_POINT",
            "cpu_state": "TRAP_SECUREFAULT"
        }

gateway = SecureGatewayVeneerTable()
legit_call = gateway.branch_from_non_secure(0x00040000)
attack_jump = gateway.branch_from_non_secure(0x10002150)

print("=== ARMv8-M Secure Gateway (SG) Veneer Audit ===")
